const r = await tools.exec_command({cmd:"python - <<'PY'
import numpy as np
from scipy.optimize import curve_fit
for f,c in [('raman_532nm_100K',233),('raman_532nm_100K',1472),('raman_532nm_300K',1501),('ir_300K',258),('ir_100K',2052)]:
 data=np.loadtxt('/app/spectra/'+f+'.csv',delimiter=',',skiprows=1); x=data[:,0];y=data[:,1]; m=(x>=c-15)&(x<=c+15);xx=x[m]; yy=y[m]
 def g(x,a,mu,s,b,k): return a*np.exp(-.5*((x-mu)/s)**2)+b+k*(x-mu)
 p,_=curve_fit(g,xx,yy,p0=[max(yy)-min(yy),c,4,np.median([yy[0],yy[-1]]),0],bounds=([0,c-15,1,0,-1e3],[1e5,c+15,15,100,1e3]),maxfev=30000)
 print(f,c,p, 'FWHM',2.355*p[2], 'resid rms',np.std(yy-g(xx,*p)))
PY",workdir:"/app",max_output_tokens:1500}); text(r.output);

