import numpy as np
for mod in ['raman_532nm','raman_785nm','ir']:
 print('\n',mod)
 for T in [100,150,200,300]:
  y=np.loadtxt(f'/app/spectra/{mod}_{T}K.csv',delimiter=',',skiprows=1)[:,1]; x=np.arange(150,2201)
  for lo,hi in [(520,545),(518,550),(495,523),(515,544)]:
   ix=(x>=lo)&(x<=hi); l=np.mean(y[(x>=lo-6)&(x<lo)]);r=np.mean(y[(x>hi)&(x<=hi+6)])
